using System.Text.Json;
using System.Text.Json.Serialization;

namespace Server;

public sealed partial class World
{
    private static readonly JsonSerializerOptions OfflineCreatureWriteJson = new()
    { Converters = { new OfflineCreatureWriter() } };

    // Write-only optimization. Restore still uses the original strict typed reader and validators.
    // Raw values are immutable bytes generated by JsonSerializer, never unchecked external JSON.
    private sealed class OfflineCreatureWriter : JsonConverter<OfflineCreature>
    {
        public override OfflineCreature Read(ref Utf8JsonReader reader, Type type, JsonSerializerOptions options)
            => JsonSerializer.Deserialize<OfflineCreature>(ref reader) ?? throw new JsonException("Missing creature.");
        public override void Write(Utf8JsonWriter writer, OfflineCreature value, JsonSerializerOptions options)
        {
            writer.WriteStartObject();
            writer.WritePropertyName(nameof(OfflineCreature.Data));
            if (value.CapturedUtf8 is { } bytes) writer.WriteRawValue(bytes, skipInputValidation: true);
            else value.Data.WriteTo(writer);
            writer.WriteNumber(nameof(OfflineCreature.OwnerId), value.OwnerId);
            writer.WriteString(nameof(OfflineCreature.OwnerKey), value.OwnerKey);
            writer.WriteBoolean(nameof(OfflineCreature.Summoned), value.Summoned);
            writer.WriteNumber(nameof(OfflineCreature.PetExpiresAt), value.PetExpiresAt);
            writer.WriteNumber(nameof(OfflineCreature.FrozenUntil), value.FrozenUntil);
            writer.WriteNumber(nameof(OfflineCreature.DamageAmp), value.DamageAmp);
            writer.WriteNumber(nameof(OfflineCreature.DamageAmpUntil), value.DamageAmpUntil);
            writer.WriteNumber(nameof(OfflineCreature.AmnesiaBy), value.AmnesiaBy);
            writer.WriteNumber(nameof(OfflineCreature.AmnesiaUntil), value.AmnesiaUntil);
            writer.WriteEndObject();
        }
    }
}
